-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다
-- (소식 표의 줄 수·표 권한·정책·칸 권한 해시 변화 없음).
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261026190000' and name='tg_sender_names')=1 then '예' else '아니오' end as value
union all select 'two new tables: RLS on, one read policy each (authenticated, owner check)',case when (select count(*) from pg_class where oid in(to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders')) and relrowsecurity and not relforcerowsecurity and coalesce(relacl::text,'')!~'(^|[{,])(anon)?=')=2 and (select count(*) from pg_policy where polrelid in(to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders')) and polcmd='r' and polroles=array['authenticated'::regrole]::oid[] and pg_get_expr(polqual,polrelid) like '%app_is_workspace_owner%')=2 and (select count(*) from pg_policy where polrelid in(to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders')))=2 then '예' else '아니오' end
union all select 'new tables: authenticated reads only, service_role and anon nothing',case when has_table_privilege('authenticated','public.app_tg_senders','select') and has_table_privilege('authenticated','public.app_tg_day_senders','select') and not has_table_privilege('authenticated','public.app_tg_senders','insert') and not has_table_privilege('authenticated','public.app_tg_senders','update') and not has_table_privilege('authenticated','public.app_tg_senders','delete') and not has_table_privilege('authenticated','public.app_tg_day_senders','insert') and not has_table_privilege('authenticated','public.app_tg_day_senders','update') and not has_table_privilege('authenticated','public.app_tg_day_senders','delete') and not has_any_column_privilege('service_role','public.app_tg_senders','select') and not has_any_column_privilege('service_role','public.app_tg_day_senders','select') and not has_any_column_privilege('anon','public.app_tg_senders','select') and not has_any_column_privilege('anon','public.app_tg_day_senders','select') then '예' else '아니오' end
union all select 'four functions: definer, empty search_path, no anon or PUBLIC execute',case when (select count(*) from pg_proc p where p.oid in(to_regprocedure('public.app_tg_senders_upsert(uuid,text,date,jsonb)'),to_regprocedure('public.app_tg_sender_set_name(text,date,text,text)'),to_regprocedure('public.app_tg_sender_merge(uuid,uuid)'),to_regprocedure('public.app_tg_sender_forget(uuid)')) and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=')=4 then '예' else '아니오' end
union all select 'upsert is service_role only, set_name and merge and forget are authenticated only',case when has_function_privilege('service_role','public.app_tg_senders_upsert(uuid,text,date,jsonb)','execute') and not has_function_privilege('authenticated','public.app_tg_senders_upsert(uuid,text,date,jsonb)','execute') and has_function_privilege('authenticated','public.app_tg_sender_set_name(text,date,text,text)','execute') and has_function_privilege('authenticated','public.app_tg_sender_merge(uuid,uuid)','execute') and has_function_privilege('authenticated','public.app_tg_sender_forget(uuid)','execute') and not has_function_privilege('service_role','public.app_tg_sender_set_name(text,date,text,text)','execute') and not has_function_privilege('service_role','public.app_tg_sender_merge(uuid,uuid)','execute') and not has_function_privilege('service_role','public.app_tg_sender_forget(uuid)','execute') then '예' else '아니오' end
union all select 'new tables start empty',case when not exists(select 1 from public.app_tg_senders) and not exists(select 1 from public.app_tg_day_senders) then '예' else '아니오' end
union all select 'no raw number column on the new tables',case when not exists(select 1 from pg_attribute where attrelid in(to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders')) and attnum>0 and not attisdropped and attname~'(phone|number|user_id|telegram|raw)') then '예' else '아니오' end
union all select 'no anon or PUBLIC table or column privilege on the feed and new tables',case when not exists(select 1 from pg_class where oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders')) and coalesce(relacl::text,'')~'(^|[{,])(anon)?=') and not exists(select 1 from pg_attribute where attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders')) and attacl::text~'(^|[{,])(anon)?=') then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'feed table grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid=to_regclass('public.app_feed_items')),'')
  ||coalesce((select string_agg(a.attname::text||':'||a.attacl::text,',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_feed_items')),''));
